"use client";
import { logoutAction } from "@/app/dashboard/action";
import { CircleUserRound, User2Icon } from "lucide-react";
import { useState, useRef, useEffect } from "react";

export default function Header() {
  const [open, setOpen] = useState(false);
  const dropdownRef = useRef();

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (!dropdownRef.current?.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <header className="text-gray-900 px-6 py-4 flex justify-end">
      <div className="relative" ref={dropdownRef}>
        
        {/* Trigger */}
        <button
          onClick={() => setOpen(!open)}
          className="rounded-full px-4 py-1 border border-gray-200 bg-white flex items-center gap-3 transition"
        >
         {/* <CircleUserRound className="w-8 h-8 text-gray-600" /> */}
          <div className="bg-gray-100 rounded-full h-8 w-8 flex justify-center items-center text-gray-800"><User2Icon /></div>
          <div className="flex flex-col space-y-0 gap-0 text-left">
            <h4 className="text-sm font-semibold">Imam Shafai</h4>
            <p className="text-xs text-gray-400">Super Admin</p>
          </div>
        </button>

        {/* Dropdown */}
        {open && (
          <div className="absolute right-0 mt-3 w-56 bg-white border border-gray-200 rounded-xl shadow-lg overflow-hidden z-50">
            {/* User Info */}
            <div className="px-4 py-3 border-b">
              <p className="text-sm font-semibold">Imam Shafai</p>
              <p className="text-xs text-gray-400">imam@example.com</p>
            </div>

            {/* Menu Items */}
            <div className="flex flex-col">
              <button className="px-4 py-2 text-sm hover:bg-gray-100 text-left">
                Profile
              </button>
              <button className="px-4 py-2 text-sm hover:bg-gray-100 text-left">
                Settings
              </button>
              <button className="px-4 py-2 text-sm hover:bg-gray-100 text-left">
                Dashboard
              </button>
            </div>

            {/* Logout */}
            <div className="border-t">
              <form action={logoutAction}>
                <button
                  type="submit"
                  className="w-full text-left px-4 py-2 text-sm text-red-500 hover:bg-red-50"
                >
                  Logout
                </button>
              </form>
            </div>
          </div>
        )}
      </div>
    </header>
  );
}
